 12→/**
 13→ * PROCESS Page - Accordion-Style Category Reveal
 14→ *
 15→ * Four categories with hover/tap to expand:
 16→ * - Case Studies: Project deep dives
 17→ * - Tools: Downloadable tools
 18→ * - Research: Blog-style methodology posts
 19→ * - Experiments: Visual scenes/prototypes
 20→ *
 21→ * Desktop: Hover to expand (150ms delay, sticky)
 22→ * Mobile: Tap to toggle
 23→ */
 24→
 25→const CATEGORY_ORDER: ProcessCategory[] = [
 26→  'case-studies',
 27→  'tools',
 28→  'research',
 29→  'experiments'
 30→];
 31→
 32→export default function ProcessPage() {
 33→  const [introVisible, setIntroVisible] = useState(false);
 34→  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
 35→  // Default to CASE STUDIES open on page load
 36→  const [expandedCategory, setExpandedCategory] = useState<ProcessCategory | null>('case-studies');
 37→
 38→  // Detect reduced motion preference
 39→  useEffect(() => {
 40→    const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
 41→    setPrefersReducedMotion(motionQuery.matches);
 42→    const handleMotionChange = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
 43→    motionQuery.addEventListener('change', handleMotionChange);
 44→    return () => motionQuery.removeEventListener('change', handleMotionChange);
 45→  }, []);
 46→
 47→  // Trigger intro animation on mount
 48→  useEffect(() => {
 49→    const timer = setTimeout(() => setIntroVisible(true), 100);
 50→    return () => clearTimeout(timer);
 51→  }, []);
 52→
 53→  // Get posts for each category
 54→  const categoryPosts = CATEGORY_ORDER.map(cat => ({
 55→    category: cat,
 56→    posts: getProcessPostsByCategory(cat)
 57→  }));
 58→
 59→  // Handle toggle - cascading behavior: closing one opens the next
 60→  const handleToggle = (category: ProcessCategory) => {
 61→    setExpandedCategory(prev => {
 62→      if (prev === category) {
 63→        // Closing current category - cascade to next
 64→        const currentIndex = CATEGORY_ORDER.indexOf(category);
 65→        const nextIndex = currentIndex + 1;
 66→        // If there's a next category, open it; otherwise close all
 67→        return nextIndex < CATEGORY_ORDER.length ? CATEGORY_ORDER[nextIndex] : null;
 68→      } else {
 69→        // Opening a different category
 70→        return category;
 71→      }
 72→    });
 73→  };
 74→
 75→  return (
 76→    <div className="min-h-screen" style={{ backgroundColor: '#141414' }}>
 77→      <main
 78→        className="mx-auto pb-32"
 79→        style={{
 80→          maxWidth: 'var(--max-content-width)',
 81→          paddingTop: 'clamp(100px, 8vw + 60px, 180px)',
 82→          paddingLeft: 'var(--side-padding)',
 83→          paddingRight: 'var(--side-padding)'
 84→        }}
 85→      >
 86→        {/* Hero Statement */}
 87→        {/* Mobile: 48px margin, Desktop: 76px */}
 88→        <section className="mb-12 sm:mb-[76px]">
 89→          <h1
 90→            style={{
 91→              color: '#a0a0a0',
 92→              fontFamily: 'var(--font-lora)',
 93→              fontWeight: 400,
 94→              fontStyle: 'italic',
 95→              fontSize: 'clamp(22px, 3.5vw, 38px)',
 96→              lineHeight: 1.3,
 97→              letterSpacing: '0.01em',
 98→              maxWidth: '900px',
 99→              opacity: introVisible ? 1 : 0,
100→              transform: introVisible ? 'translateY(0)' : 'translateY(30px)',
101→              transition: prefersReducedMotion ? 'none' : 'opacity 550ms cubic-bezier(0.25, 0.1, 0.25, 1) 100ms, transform 550ms cubic-bezier(0.25, 0.1, 0.25, 1) 100ms'
102→            }}
103→          >
104→            Behind the final frame: tools built, problems solved, and the thinking that shapes the work.
105→          </h1>
106→        </section>
107→
108→        {/* Accordion Categories */}
109→        <div
110→          style={{
111→            opacity: introVisible ? 1 : 0,
112→            transform: introVisible ? 'translateY(0)' : 'translateY(20px)',
113→            transition: prefersReducedMotion ? 'none' : 'opacity 550ms ease 200ms, transform 550ms ease 200ms'
114→          }}
115→        >
116→          {categoryPosts.map(({ category, posts }) => (
117→            <AccordionCategory
118→              key={category}
119→              title={categoryLabels[category]}
120→              count={posts.length}
121→              isExpanded={expandedCategory === category}
122→              onToggle={() => handleToggle(category)}
123→              prefersReducedMotion={prefersReducedMotion}
124→            >
125→              {/* Item List - vertical stack like INFO page */}
126→              {/* Mobile: 24px gap, Desktop: 32px gap */}
127→              {/* Pentagram-style generous vertical rhythm */}
128→              <div className="flex flex-col gap-8 sm:gap-12">
129→                {posts.map((post) => (
130→                  <ProcessThumbnail
131→                    key={post.id}
132→                    slug={post.slug}
133→                    title={post.title}
134→                    excerpt={post.excerpt}
135→                    version={post.version}
136→                    thumbnail={post.thumbnail}
137→                    githubUrl={post.githubUrl}
138→                  />
139→                ))}
140→              </div>
141→
142→              {/* Empty state */}
143→              {posts.length === 0 && (
144→                <p
145→                  style={{
146→                    color: '#5a5a5a',
147→                    fontFamily: 'var(--font-open-sans)',
148→                    fontSize: '14px',
149→                    fontStyle: 'italic'
150→                  }}
151→                >
152→                  Coming soon.
153→                </p>
154→              )}
155→            </AccordionCategory>
156→          ))}
157→        </div>
158→      </main>
159→    </div>
160→  );
161→}
