24→interface VimeoVideo {
25→  name: string;
26→  description: string | null;
27→  uri: string;
28→  duration: number;
29→}
30→
31→/**
32→ * Fetch video metadata from Vimeo API
33→ * @param videoId - The Vimeo video ID
34→ * @returns Video metadata including title and description
35→ */
36→export async function fetchVimeoVideo(videoId: string): Promise<VimeoVideo | null> {
37→  const accessToken = process.env.VIMEO_ACCESS_TOKEN;
38→
39→  if (!accessToken) {
40→    console.warn('VIMEO_ACCESS_TOKEN not configured');
41→    return null;
42→  }
43→
44→  try {
45→    const response = await fetch(`https://api.vimeo.com/videos/${videoId}`, {
46→      headers: {
47→        'Authorization': `bearer ${accessToken}`,
48→        'Accept': 'application/vnd.vimeo.*+json;version=3.4'
49→      }
50→    });
51→
52→    if (!response.ok) {
53→      console.error(`Vimeo API error for video ${videoId}: ${response.statusText}`);
54→      return null;
55→    }
56→
57→    const data = await response.json();
58→
59→    return {
60→      name: data.name,
61→      description: data.description,
62→      uri: data.uri,
63→      duration: data.duration
64→    };
65→  } catch (error) {
66→    console.error(`Error fetching Vimeo video ${videoId}:`, error);
67→    return null;
68→  }
69→}
70→
71→/**
72→ * Batch fetch multiple Vimeo videos
73→ * @param videoIds - Array of Vimeo video IDs
74→ * @returns Map of videoId to video metadata
75→ */
76→export async function fetchVimeoVideos(videoIds: string[]): Promise<Map<string, VimeoVideo>> {
77→  const videoMap = new Map<string, VimeoVideo>();
78→
79→  // Fetch all videos in parallel
80→  const results = await Promise.all(
81→    videoIds.map(async (videoId) => {
82→      const video = await fetchVimeoVideo(videoId);
83→      return { videoId, video };
84→    })
85→  );
86→
87→  // Build map
88→  results.forEach(({ videoId, video }) => {
89→    if (video) {
90→      videoMap.set(videoId, video);
91→    }
92→  });
93→
94→  return videoMap;
95→}
