 1→/**
 2→ * Adaptation Engine
 3→ * Reorders projects based on detected visitor archetype
 4→ */
 5→
 6→import { VisitorArchetype } from './types';
 7→import type { Project } from '@/lib/projects';
 8→
 9→/**
10→ * Adaptation strategies for different visitor archetypes
11→ */
12→export class ProjectAdapter {
13→  /**
14→   * Reorder projects based on visitor archetype
15→   *
16→   * Fast Scanner → Hero shots first (visually striking work)
17→   * Technical Explorer → R&D/Experimental first (complex technical work)
18→   * Casual Browser → Default order (featured/everything)
19→   */
20→  static adaptProjectOrder(projects: Project[], archetype: VisitorArchetype): Project[] {
21→    // Don't adapt for unknown visitors
22→    if (archetype === VisitorArchetype.UNKNOWN) {
23→      return projects;
24→    }
25→
26→    const projectsCopy = [...projects];
27→
28→    switch (archetype) {
29→      case VisitorArchetype.FAST_SCANNER:
30→        return this.optimizeForFastScanner(projectsCopy);
31→
32→      case VisitorArchetype.TECHNICAL_EXPLORER:
33→        return this.optimizeForTechnicalExplorer(projectsCopy);
34→
35→      case VisitorArchetype.CASUAL_BROWSER:
36→      default:
37→        return projectsCopy; // Keep default order
38→    }
39→  }
40→
41→  /**
42→   * Fast Scanner optimization:
43→   * Prioritize visually striking, hero projects
44→   * Categories: Direction, Commissions (high-profile work)
45→   */
46→  private static optimizeForFastScanner(projects: Project[]): Project[] {
47→    const heroKeywords = ['direction', 'commissions', 'commercial'];
48→
49→    return projects.sort((a, b) => {
50→      const aIsHero = this.matchesKeywords(a, heroKeywords);
51→      const bIsHero = this.matchesKeywords(b, heroKeywords);
52→
53→      if (aIsHero && !bIsHero) return -1;
54→      if (!aIsHero && bIsHero) return 1;
55→      return 0; // Keep original order within groups
56→    });
57→  }
58→
59→  /**
60→   * Technical Explorer optimization:
61→   * Prioritize R&D, experimental, and technically complex work
62→   * Categories: R&D, Experimental, Lighting (technical specialty)
63→   */
64→  private static optimizeForTechnicalExplorer(projects: Project[]): Project[] {
65→    const technicalKeywords = ['r&d', 'experimental', 'lighting', 'technical'];
66→
67→    return projects.sort((a, b) => {
68→      const aIsTechnical = this.matchesKeywords(a, technicalKeywords);
69→      const bIsTechnical = this.matchesKeywords(b, technicalKeywords);
70→
71→      if (aIsTechnical && !bIsTechnical) return -1;
72→      if (!aIsTechnical && bIsTechnical) return 1;
73→      return 0;
74→    });
75→  }
76→
77→  /**
78→   * Check if project matches any keywords in title, disciplines, or tags
79→   */
80→  private static matchesKeywords(project: Project, keywords: string[]): boolean {
81→    const searchText = [
82→      project.title,
83→      ...(project.disciplines || []),
84→    ]
85→      .filter(Boolean)
86→      .join(' ')
87→      .toLowerCase();
88→
89→    return keywords.some(keyword => searchText.includes(keyword.toLowerCase()));
90→  }
91→}
