  1→/**
  2→ * Visitor Archetype Classifier
  3→ * Phase 2: USD Substrate Integration
  4→ *
  5→ * Enhanced with:
  6→ * - Chat behavior signals
  7→ * - Confidence evolution based on stability
  8→ * - Archetype transitions during session
  9→ */
 10→
 11→import { SensorEvent, SensorEventType, VisitorArchetype, VisitorProfile } from './types';
 12→
 13→// Technical terms that indicate a TECHNICAL_EXPLORER
 14→const TECHNICAL_TERMS = [
 15→  'usd', 'solaris', 'houdini', 'karma', 'katana', 'renderman', 'arnold',
 16→  'nuke', 'compositing', 'render', 'shader', 'material', 'texture',
 17→  'pipeline', 'workflow', 'hda', 'vex', 'python', 'api', 'livrps',
 18→  'lumen', 'nanite', 'unreal', 'real-time', 'gpu', 'xpu',
 19→  'fur', 'lighting', 'lookdev', 'aov', 'deep', 'cryptomatte',
 20→  'procedural', 'instancing', 'optimization', 'performance'
 21→];
 22→
 23→export class VisitorClassifier {
 24→  private events: SensorEvent[] = [];
 25→  private archetypeHistory: VisitorArchetype[] = [];
 26→  private lastArchetype: VisitorArchetype = VisitorArchetype.UNKNOWN;
 27→  private consecutiveSameArchetype: number = 0;
 28→  private totalClassifications: number = 0;
 29→
 30→  /**
 31→   * Add new sensor event to analysis buffer
 32→   */
 33→  addEvent(event: SensorEvent) {
 34→    this.events.push(event);
 35→
 36→    // Keep only last 150 events for performance (increased for chat events)
 37→    if (this.events.length > 150) {
 38→      this.events = this.events.slice(-150);
 39→    }
 40→  }
 41→
 42→  /**
 43→   * Classify visitor based on behavioral patterns
 44→   * Requires minimum 10 events for reliable classification
 45→   */
 46→  classify(): VisitorProfile {
 47→    const metrics = this.calculateMetrics();
 48→
 49→    if (this.events.length < 10) {
 50→      return {
 51→        archetype: VisitorArchetype.UNKNOWN,
 52→        confidence: 0,
 53→        metrics,
 54→        stability: {
 55→          consecutiveSameArchetype: 0,
 56→          totalClassifications: 0,
 57→          archetypeHistory: [],
 58→        },
 59→        lastUpdated: Date.now(),
 60→      };
 61→    }
 62→
 63→    const archetype = this.determineArchetype(metrics);
 64→    this.updateStability(archetype);
 65→    const confidence = this.calculateConfidence(metrics, archetype);
 66→
 67→    return {
 68→      archetype,
 69→      confidence,
 70→      metrics,
 71→      stability: {
 72→        consecutiveSameArchetype: this.consecutiveSameArchetype,
 73→        totalClassifications: this.totalClassifications,
 74→        archetypeHistory: [...this.archetypeHistory].slice(-10),
 75→      },
 76→      lastUpdated: Date.now(),
 77→    };
 78→  }
 79→
 80→  /**
 81→   * Track archetype stability for confidence evolution
 82→   */
 83→  private updateStability(archetype: VisitorArchetype) {
 84→    this.totalClassifications++;
 85→
 86→    if (archetype === this.lastArchetype) {
 87→      this.consecutiveSameArchetype++;
 88→    } else {
 89→      this.consecutiveSameArchetype = 1;
 90→      this.lastArchetype = archetype;
 91→    }
 92→
 93→    // Keep last 10 archetypes for oscillation detection
 94→    this.archetypeHistory.push(archetype);
 95→    if (this.archetypeHistory.length > 10) {
 96→      this.archetypeHistory.shift();
 97→    }
 98→  }
 99→
100→  /**
101→   * Calculate behavioral metrics from events
102→   * Now includes chat behavior signals
103→   */
104→  private calculateMetrics(): VisitorProfile['metrics'] {
105→    const scrollEvents = this.events.filter(e => e.type === SensorEventType.SCROLL);
106→    const clickEvents = this.events.filter(e => e.type === SensorEventType.CLICK);
107→    const projectDetailClicks = clickEvents.filter(e =>
108→      e.data.target?.includes('project') || e.data.projectSlug
109→    );
110→    const chatMessages = this.events.filter(e => e.type === SensorEventType.CHAT_MESSAGE);
111→    const chatResponseReads = this.events.filter(e => e.type === SensorEventType.CHAT_RESPONSE_READ);
112→
113→    // Browsing metrics
114→    const scrollVelocities = scrollEvents
115→      .map(e => e.data.scrollVelocity)
116→      .filter((v): v is number => v !== undefined);
117→    const avgScrollVelocity = scrollVelocities.length > 0
118→      ? scrollVelocities.reduce((a, b) => a + b, 0) / scrollVelocities.length
119→      : 0;
120→
121→    const pageViews = this.events.filter(e => e.type === SensorEventType.PAGE_VIEW);
122→    const dwellTimes = pageViews
123→      .map(e => e.data.dwellTime)
124→      .filter((t): t is number => t !== undefined);
125→    const avgDwellTime = dwellTimes.length > 0
126→      ? dwellTimes.reduce((a, b) => a + b, 0) / dwellTimes.length
127→      : 0;
128→
129→    // Chat metrics
130→    const messageLengths = chatMessages
131→      .map(e => e.data.messageLength)
132→      .filter((l): l is number => l !== undefined);
133→    const avgMessageLength = messageLengths.length > 0
134→      ? messageLengths.reduce((a, b) => a + b, 0) / messageLengths.length
135→      : 0;
136→
137→    const technicalTermCount = chatMessages
138→      .filter(e => e.data.hasTechnicalTerms)
139→      .length;
140→
141→    const responseReadTimes = chatResponseReads
142→      .map(e => e.data.responseReadTime)
143→      .filter((t): t is number => t !== undefined);
144→    const avgResponseReadTime = responseReadTimes.length > 0
145→      ? responseReadTimes.reduce((a, b) => a + b, 0) / responseReadTimes.length
146→      : 0;
147→
148→    const followUps = chatMessages.filter(e => e.data.isFollowUp).length;
149→    const followUpRatio = chatMessages.length > 0
150→      ? followUps / chatMessages.length
151→      : 0;
152→
153→    return {
154→      avgScrollVelocity,
155→      clickCount: clickEvents.length,
156→      avgDwellTime,
157→      projectDetailClicks: projectDetailClicks.length,
158→      chatMessageCount: chatMessages.length,
159→      avgMessageLength,
160→      technicalTermCount,
161→      avgResponseReadTime,
162→      followUpRatio,
163→    };
164→  }
165→
166→  /**
167→   * Determine archetype from metrics using rule-based logic
168→   * Enhanced with chat behavior signals
169→   */
170→  private determineArchetype(metrics: VisitorProfile['metrics']): VisitorArchetype {
171→    const {
172→      avgScrollVelocity,
173→      clickCount,
174→      avgDwellTime,
175→      projectDetailClicks,
176→      chatMessageCount,
177→      avgMessageLength,
178→      technicalTermCount,
179→      avgResponseReadTime,
180→      followUpRatio,
181→    } = metrics;
182→
183→    // Chat signals can strongly influence archetype
184→    const hasChatSignals = chatMessageCount > 0;
185→
186→    if (hasChatSignals) {
187→      // TECHNICAL_EXPLORER via chat:
188→      // - Uses technical terms
189→      // - Longer messages (asking detailed questions)
190→      // - High follow-up ratio (digging deeper)
191→      // - Longer response read times (actually reading)
192→      if (
193→        technicalTermCount >= 2 ||
194→        (avgMessageLength > 100 && followUpRatio > 0.5) ||
195→        (avgResponseReadTime > 8000 && technicalTermCount >= 1)
196→      ) {
197→        return VisitorArchetype.TECHNICAL_EXPLORER;
198→      }
199→
200→      // FAST_SCANNER via chat:
201→      // - Short messages
202→      // - Quick response reads (skimming)
203→      // - Low follow-up ratio (moving on quickly)
204→      if (
205→        avgMessageLength < 50 &&
206→        avgResponseReadTime < 3000 &&
207→        followUpRatio < 0.3 &&
208→        chatMessageCount >= 2
209→      ) {
210→        return VisitorArchetype.FAST_SCANNER;
211→      }
212→    }
213→
214→    // Fall back to browsing behavior signals
215→    // Fast Scanner: High scroll velocity, low clicks, short dwell
216→    if (avgScrollVelocity > 800 && avgDwellTime < 3000 && clickCount < 3) {
217→      return VisitorArchetype.FAST_SCANNER;
218→    }
219→
220→    // Technical Explorer: Low scroll velocity, high detail clicks, long dwell
221→    if (avgScrollVelocity < 300 && projectDetailClicks > 2 && avgDwellTime > 5000) {
222→      return VisitorArchetype.TECHNICAL_EXPLORER;
223→    }
224→
225→    // Technical Explorer (alternative: high engagement)
226→    if (clickCount > 5 && projectDetailClicks > 1 && avgScrollVelocity < 500) {
227→      return VisitorArchetype.TECHNICAL_EXPLORER;
228→    }
229→
230→    // Default: Casual Browser
231→    return VisitorArchetype.CASUAL_BROWSER;
232→  }
233→
234→  /**
235→   * Calculate confidence score with stability evolution
236→   *
237→   * Confidence grows when:
238→   * - Metrics strongly match the archetype
239→   * - Classification has been stable (same archetype consecutively)
240→   * - More events have been accumulated
241→   *
242→   * Confidence shrinks when:
243→   * - Oscillating between archetypes
244→   * - Weak metric matches
245→   */
246→  private calculateConfidence(
247→    metrics: VisitorProfile['metrics'],
248→    archetype: VisitorArchetype
249→  ): number {
250→    // Base confidence from metric strength
251→    const baseConfidence = this.calculateBaseConfidence(metrics, archetype);
252→
253→    // Stability multiplier (0.8 to 1.2)
254→    // Rewards consistent classification, penalizes oscillation
255→    const stabilityMultiplier = this.calculateStabilityMultiplier();
256→
257→    // Event count factor (0.7 to 1.0)
258→    // More events = more confidence (up to a point)
259→    const eventFactor = Math.min(1.0, 0.7 + (this.events.length / 100) * 0.3);
260→
261→    // Final confidence, clamped to 0-1
262→    const finalConfidence = baseConfidence * stabilityMultiplier * eventFactor;
263→    return Math.min(1.0, Math.max(0, finalConfidence));
264→  }
265→
266→  /**
267→   * Calculate base confidence from how strongly metrics match archetype
268→   */
269→  private calculateBaseConfidence(
270→    metrics: VisitorProfile['metrics'],
271→    archetype: VisitorArchetype
272→  ): number {
273→    const {
274→      avgScrollVelocity,
275→      clickCount,
276→      avgDwellTime,
277→      projectDetailClicks,
278→      chatMessageCount,
279→      avgMessageLength,
280→      technicalTermCount,
281→      avgResponseReadTime,
282→      followUpRatio,
283→    } = metrics;
284→
285→    switch (archetype) {
286→      case VisitorArchetype.FAST_SCANNER: {
287→        let confidence = 0;
288→
289→        // Browsing signals
290→        if (avgScrollVelocity > 1000) confidence += 0.25;
291→        else if (avgScrollVelocity > 800) confidence += 0.15;
292→
293→        if (avgDwellTime < 2000) confidence += 0.2;
294→        else if (avgDwellTime < 3000) confidence += 0.1;
295→
296→        if (clickCount < 2) confidence += 0.2;
297→        else if (clickCount < 3) confidence += 0.1;
298→
299→        // Chat signals boost/confirm
300→        if (chatMessageCount > 0) {
301→          if (avgMessageLength < 40) confidence += 0.15;
302→          if (avgResponseReadTime < 2000) confidence += 0.15;
303→          if (followUpRatio < 0.2) confidence += 0.1;
304→        }
305→
306→        return Math.min(confidence, 1.0);
307→      }
308→
309→      case VisitorArchetype.TECHNICAL_EXPLORER: {
310→        let confidence = 0;
311→
312→        // Browsing signals
313→        if (avgScrollVelocity < 200) confidence += 0.2;
314→        else if (avgScrollVelocity < 300) confidence += 0.1;
315→
316→        if (projectDetailClicks > 3) confidence += 0.25;
317→        else if (projectDetailClicks > 2) confidence += 0.15;
318→
319→        if (avgDwellTime > 10000) confidence += 0.2;
320→        else if (avgDwellTime > 5000) confidence += 0.1;
321→
322→        // Chat signals can strongly boost
323→        if (chatMessageCount > 0) {
324→          if (technicalTermCount >= 3) confidence += 0.25;
325→          else if (technicalTermCount >= 1) confidence += 0.15;
326→
327→          if (avgMessageLength > 150) confidence += 0.15;
328→          else if (avgMessageLength > 100) confidence += 0.1;
329→
330→          if (followUpRatio > 0.6) confidence += 0.15;
331→          else if (followUpRatio > 0.4) confidence += 0.1;
332→
333→          if (avgResponseReadTime > 10000) confidence += 0.1;
334→        }
335→
336→        return Math.min(confidence, 1.0);
337→      }
338→
339→      case VisitorArchetype.CASUAL_BROWSER:
340→        // Medium confidence for default category
341→        // Slightly lower to encourage eventual classification
342→        return 0.55;
343→
344→      default:
345→        return 0;
346→    }
347→  }
348→
349→  /**
350→   * Calculate stability multiplier based on classification history
351→   */
352→  private calculateStabilityMultiplier(): number {
353→    if (this.totalClassifications < 3) {
354→      // Too early to judge stability
355→      return 1.0;
356→    }
357→
358→    // Reward stability: same archetype for 5+ consecutive = 1.2x
359→    if (this.consecutiveSameArchetype >= 5) {
360→      return 1.2;
361→    } else if (this.consecutiveSameArchetype >= 3) {
362→      return 1.1;
363→    }
364→
365→    // Penalize oscillation: check if bouncing between archetypes
366→    if (this.archetypeHistory.length >= 4) {
367→      const recent = this.archetypeHistory.slice(-4);
368→      const unique = new Set(recent);
369→      if (unique.size >= 3) {
370→        // High oscillation - reduce confidence
371→        return 0.8;
372→      }
373→    }
374→
375→    return 1.0;
376→  }
377→
378→  /**
379→   * Reset classifier state
380→   */
381→  reset() {
382→    this.events = [];
383→    this.archetypeHistory = [];
384→    this.lastArchetype = VisitorArchetype.UNKNOWN;
385→    this.consecutiveSameArchetype = 0;
386→    this.totalClassifications = 0;
387→  }
388→}
