390→/**
391→ * Analyze a chat message for signals
392→ * Used by ChatBot to generate CHAT_MESSAGE events
393→ */
394→export function analyzeChatMessage(message: string, isFollowUp: boolean): {
395→  messageLength: number;
396→  wordCount: number;
397→  hasTechnicalTerms: boolean;
398→  isFollowUp: boolean;
399→  questionCategory: 'process' | 'outcome' | 'contact' | 'personal' | 'general';
400→} {
401→  const lowerMessage = message.toLowerCase();
402→  const words = message.trim().split(/\s+/);
403→
404→  // Check for technical terms
405→  const hasTechnicalTerms = TECHNICAL_TERMS.some(term =>
406→    lowerMessage.includes(term)
407→  );
408→
409→  // Determine question category
410→  let questionCategory: 'process' | 'outcome' | 'contact' | 'personal' | 'general' = 'general';
411→
412→  if (/\b(how|process|workflow|technique|approach|method)\b/i.test(message)) {
413→    questionCategory = 'process';
414→  } else if (/\b(project|client|work|result|outcome|portfolio)\b/i.test(message)) {
415→    questionCategory = 'outcome';
416→  } else if (/\b(contact|email|hire|available|reach|availability)\b/i.test(message)) {
417→    questionCategory = 'contact';
418→  } else if (/\b(personal|live|location|hobby|dog|brooklyn)\b/i.test(message)) {
419→    questionCategory = 'personal';
420→  }
421→
422→  return {
423→    messageLength: message.length,
424→    wordCount: words.length,
425→    hasTechnicalTerms,
426→    isFollowUp,
427→    questionCategory,
428→  };
429→}
