 3→import { useState, useEffect } from 'react';
 4→
 5→/**
 6→ * Shared reduced-motion preference hook
 7→ *
 8→ * Listens for OS-level prefers-reduced-motion setting.
 9→ * Updates reactively if the user toggles the preference.
10→ */
11→export function usePrefersReducedMotion(): boolean {
12→  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
13→
14→  useEffect(() => {
15→    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
16→    setPrefersReducedMotion(mq.matches);
17→
18→    const handler = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
19→    mq.addEventListener('change', handler);
20→
21→    return () => mq.removeEventListener('change', handler);
22→  }, []);
23→
24→  return prefersReducedMotion;
25→}
